import { Schema } from 'effect'
import { WorkspaceId } from './scalars'

export const WorkflowId = Schema.NonEmptyString
export type WorkflowId = typeof WorkflowId.Type

export const WorkflowSlotKind = Schema.Literals(['tool', 'input'])
export type WorkflowSlotKind = typeof WorkflowSlotKind.Type

export const WorkflowToolSlot = Schema.Struct({
  kind: Schema.Literal('tool'),
  slug: Schema.String,
})
export type WorkflowToolSlot = typeof WorkflowToolSlot.Type

export const WorkflowInputSlot = Schema.Struct({
  kind: Schema.Literal('input'),
  slug: Schema.String,
})
export type WorkflowInputSlot = typeof WorkflowInputSlot.Type

export const WorkflowSlot = Schema.Union([WorkflowToolSlot, WorkflowInputSlot])
export type WorkflowSlot = typeof WorkflowSlot.Type

export const WorkflowOrGroup = Schema.Array(WorkflowSlot)
export type WorkflowOrGroup = typeof WorkflowOrGroup.Type

export const Workflow = Schema.Struct({
  id: WorkflowId,
  title: Schema.String,
  description: Schema.String,
  category: Schema.String,
  defaultTools: Schema.Array(WorkflowToolSlot),
  orGroups: Schema.Array(WorkflowOrGroup),
  optionalTools: Schema.Array(WorkflowToolSlot),
  bodyMarkdown: Schema.String,
  contentHash: Schema.String,
})
export type Workflow = typeof Workflow.Type

export const WorkflowOwnerKind = Schema.Literals(['system', 'workspace'])
export type WorkflowOwnerKind = typeof WorkflowOwnerKind.Type

export const WorkflowUserSummary = Schema.Struct({
  id: Schema.String,
  name: Schema.NullOr(Schema.String),
  email: Schema.NullOr(Schema.String),
  avatar_url: Schema.NullOr(Schema.String),
})
export type WorkflowUserSummary = typeof WorkflowUserSummary.Type

export const WorkflowUserSummarySchema = Schema.Struct({
  id: Schema.String,
  name: Schema.optional(Schema.NullOr(Schema.String)),
  email: Schema.optional(Schema.NullOr(Schema.String)),
  avatar_url: Schema.optional(Schema.NullOr(Schema.String)),
})
export type WorkflowUserSummaryWire = typeof WorkflowUserSummarySchema.Type

export const WorkflowPluginRequirement = Schema.Struct({
  slug: Schema.String,
  kind: Schema.optional(Schema.Literals(['mcp', 'cli', 'api'])),
  optional: Schema.optional(Schema.Boolean),
})
export type WorkflowPluginRequirement = typeof WorkflowPluginRequirement.Type

export const WorkflowSourceBinding = Schema.Struct({
  slug: Schema.optional(Schema.String),
  namespace: Schema.optional(Schema.String),
  source_id: Schema.optional(Schema.String),
})
export type WorkflowSourceBinding = typeof WorkflowSourceBinding.Type

const WorkflowEntryShape = {
  id: Schema.String,
  title: Schema.String,
  description: Schema.String,
  category: Schema.optional(Schema.String),
  content_hash: Schema.String,
  owner_kind: WorkflowOwnerKind,
  workspace_id: Schema.NullOr(Schema.String),
  updated_by_user: Schema.NullOr(WorkflowUserSummarySchema),
  version_name: Schema.NullOr(Schema.String),
  version_number: Schema.NullOr(Schema.Number),
  updated_at: Schema.optional(Schema.String),
  default_tools: Schema.Array(Schema.Unknown),
  or_groups: Schema.Array(Schema.Unknown),
  optional_tools: Schema.Array(Schema.Unknown),
}

export const WorkflowListEntrySchema = Schema.Struct(WorkflowEntryShape)
export type WorkflowListEntryWire = typeof WorkflowListEntrySchema.Type

export const WorkflowListResponseSchema = Schema.Struct({
  workflows: Schema.Array(WorkflowListEntrySchema),
})
export type WorkflowListResponseWire = typeof WorkflowListResponseSchema.Type

export const WorkflowGetResponseSchema = Schema.Struct({
  ...WorkflowEntryShape,
  body_markdown: Schema.optional(Schema.String),
})
export type WorkflowGetResponseWire = typeof WorkflowGetResponseSchema.Type

export const WorkflowListBodySchema = Schema.Struct({
  workspace_id: WorkspaceId,
})
export type WorkflowListBodyWire = typeof WorkflowListBodySchema.Type

export const WorkflowGetBodySchema = Schema.Struct({
  workspace_id: WorkspaceId,
  workflow_id: WorkflowId,
})
export type WorkflowGetBodyWire = typeof WorkflowGetBodySchema.Type

export const WorkflowAddBodySchema = Schema.Struct({
  workspace_id: WorkspaceId,
  workflow_id: WorkflowId,
})
export type WorkflowAddBodyWire = typeof WorkflowAddBodySchema.Type

export const WorkflowRemoveBodySchema = Schema.Struct({
  workspace_id: WorkspaceId,
  workflow_id: WorkflowId,
})
export type WorkflowRemoveBodyWire = typeof WorkflowRemoveBodySchema.Type

export const WorkflowCatalogEntry = Schema.Struct({
  id: Schema.String,
  title: Schema.String,
  description: Schema.String,
  category: Schema.String,
  content_hash: Schema.String,
  owner_kind: WorkflowOwnerKind,
  workspace_id: Schema.NullOr(Schema.String),
  updated_by_user: Schema.NullOr(WorkflowUserSummary),
  latest_version_id: Schema.NullOr(Schema.String),
  version_name: Schema.NullOr(Schema.String),
  version_number: Schema.NullOr(Schema.Number),
  version_sequence: Schema.Number,
  last_published_at: Schema.NullOr(Schema.String),
  last_published_by: Schema.NullOr(Schema.String),
  created_by: Schema.NullOr(Schema.String),
  updated_by: Schema.NullOr(Schema.String),
  created_at: Schema.String,
  updated_at: Schema.String,
  plugin_requirements: Schema.Array(WorkflowPluginRequirement),
  source_bindings: Schema.Array(WorkflowSourceBinding),
  default_tools: Schema.Array(WorkflowToolSlot),
  or_groups: Schema.Array(WorkflowOrGroup),
  optional_tools: Schema.Array(WorkflowToolSlot),
})
export type WorkflowCatalogEntry = typeof WorkflowCatalogEntry.Type

export const WorkflowListResponse = Schema.Struct({
  workflows: Schema.Array(WorkflowCatalogEntry),
})
export type WorkflowListResponse = typeof WorkflowListResponse.Type

export const WorkflowGetResponse = Schema.Struct({
  ...WorkflowCatalogEntry.fields,
  body_markdown: Schema.String,
})
export type WorkflowGetResponse = typeof WorkflowGetResponse.Type

export interface WorkflowSkillListRow {
  readonly id: string
  readonly title: string
  readonly owner: string
  readonly owner_kind: 'system' | 'workspace'
  readonly updated_at: string
  readonly description: string
  readonly updated_by: string
  readonly version: string
}

export interface WorkflowSkillDetail {
  readonly id: string
  readonly title: string
  readonly owner: string
  readonly owner_kind: 'system' | 'workspace'
  readonly updated_at: string | null
  readonly description: string
  readonly updated_by: string
  readonly version: string
  readonly body_markdown?: string | undefined
  readonly content_hash: string
  readonly default_tools: readonly unknown[]
  readonly or_groups: readonly unknown[]
  readonly optional_tools: readonly unknown[]
}

export function workflowOwnerLabel(entry: WorkflowListEntryWire | WorkflowGetResponseWire): string {
  return entry.owner_kind === 'system' ? 'Harbor' : 'Workspace'
}

export function workflowUpdatedByLabel(
  entry: WorkflowListEntryWire | WorkflowGetResponseWire
): string {
  return entry.updated_by_user?.name ?? entry.updated_by_user?.email ?? '-'
}

export function workflowVersionLabel(
  entry: WorkflowListEntryWire | WorkflowGetResponseWire
): string {
  return entry.version_name ?? (entry.version_number ? `v${entry.version_number}` : '-')
}

export function workflowSkillListRow(entry: WorkflowListEntryWire): WorkflowSkillListRow {
  return {
    id: entry.id,
    title: entry.title,
    owner: workflowOwnerLabel(entry),
    owner_kind: entry.owner_kind,
    updated_at: entry.updated_at ?? '-',
    description: entry.description,
    updated_by: workflowUpdatedByLabel(entry),
    version: workflowVersionLabel(entry),
  }
}

export function workflowSkillDetail(entry: WorkflowGetResponseWire): WorkflowSkillDetail {
  return {
    id: entry.id,
    title: entry.title,
    description: entry.description,
    owner: workflowOwnerLabel(entry),
    owner_kind: entry.owner_kind,
    updated_by: workflowUpdatedByLabel(entry),
    updated_at: entry.updated_at ?? null,
    version: workflowVersionLabel(entry),
    body_markdown: entry.body_markdown,
    content_hash: entry.content_hash,
    default_tools: entry.default_tools,
    or_groups: entry.or_groups,
    optional_tools: entry.optional_tools,
  }
}

function workflowToolSlotName(value: unknown): string {
  if (typeof value === 'string') return value
  if (typeof value !== 'object' || value === null) return String(value)
  const record = value as Record<string, unknown>
  const slug = record.slug ?? record.id ?? record.name
  const kind = record.kind
  if (typeof slug === 'string' && typeof kind === 'string' && kind !== 'tool')
    return `${kind}:${slug}`
  if (typeof slug === 'string') return slug
  return JSON.stringify(value)
}

export function workflowToolRequirementsToon(entry: {
  readonly default_tools: readonly unknown[]
  readonly or_groups: readonly unknown[]
  readonly optional_tools: readonly unknown[]
}): string {
  const lines: string[] = []
  if (entry.default_tools.length > 0) {
    lines.push('required_tools:')
    for (const tool of entry.default_tools) lines.push(`  - ${workflowToolSlotName(tool)}`)
  }
  if (entry.or_groups.length > 0) {
    lines.push('one_of_groups:')
    entry.or_groups.forEach((group, index) => {
      const choices = Array.isArray(group)
        ? group.map(workflowToolSlotName).join(' | ')
        : workflowToolSlotName(group)
      lines.push(`  ${index + 1}: ${choices}`)
    })
  }
  if (entry.optional_tools.length > 0) {
    lines.push('optional_tools:')
    for (const tool of entry.optional_tools) lines.push(`  - ${workflowToolSlotName(tool)}`)
  }
  return lines.join('\n')
}

export function workflowCatalogMap(entries: ReadonlyArray<WorkflowListEntryWire>) {
  return new Map(
    entries.map((entry) => [
      entry.id,
      {
        slug: entry.id,
        content_hash: entry.content_hash,
        owner_kind: entry.owner_kind,
      },
    ])
  )
}

export function workflowIsToolSlug(slug: string): boolean {
  return slug.endsWith('-mcp') || slug.endsWith('-cli') || slug.endsWith('-api')
}

export function workflowIsInputSlug(slug: string): boolean {
  return !workflowIsToolSlug(slug)
}
